package cn.pawday.care;
import cn.pawday.audit.AuditWriter;
import cn.pawday.common.Api.Failure;
import cn.pawday.common.IdempotentCommandExecutor;
import cn.pawday.identity.*;
import cn.pawday.publishing.PublishingSupport;
import static cn.pawday.publishing.PublishingSupport.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.stereotype.Service;
@Service public class InvoiceService {
 private final PublishingSupport p;private final IdempotentCommandExecutor commands;private final AuditWriter audit;private final Crypto crypto;private final AuthService auth;
 public InvoiceService(PublishingSupport p,IdempotentCommandExecutor commands,AuditWriter audit,Crypto crypto,AuthService auth){this.p=p;this.commands=commands;this.audit=audit;this.crypto=crypto;this.auth=auth;}
 private void consumer(Actor a){if(a.realm()!=Actor.Realm.CONSUMER||a.userId()==null)throw new Failure(403,"PERMISSION_DENIED");}
 private void staff(Actor a){if(a.realm()==Actor.Realm.CONSUMER||!a.permissions().contains("invoice.read"))throw new Failure(403,"PERMISSION_DENIED");}
 private String merchantScope(Actor a){return " AND s.merchant_id=? AND NOT EXISTS (SELECT 1 FROM order_items it WHERE it.suborder_id=s.id AND ((it.store_id IS NULL AND "+(!a.permissions().contains("order.default-scope"))+" ) OR (it.store_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM principal_store_scope ps WHERE ps.principal_id=? AND ps.merchant_id=s.merchant_id AND ps.store_id=it.store_id))))";}
 private final String select="SELECT i.*,s.order_id,s.merchant_id,s.merchant_name,s.suborder_no,s.payable_amount_fen FROM invoice_applications i JOIN suborders s ON s.id=i.suborder_id JOIN orders o ON o.id=s.order_id";
 private Map<String,Object> view(Map<String,Object> row,boolean privateData){var v=p.view(row);v.remove("private_cipher");v.put("issuer_notice","申请由子订单商家处理；已受理不代表已开具税务发票。");if(privateData){var raw=p.json.readValue(new String(crypto.decrypt(row.get("private_cipher").toString()),StandardCharsets.UTF_8),Map.class);v.put("title",raw.get("title"));v.put("tax_number",raw.get("tax_number"));v.put("email",raw.get("email"));}return v;}
 public List<Map<String,Object>> list(Actor a,UUID cursor,int limit){limit(limit);List<Map<String,Object>>rows;if(a.realm()==Actor.Realm.CONSUMER){consumer(a);rows=p.db.queryForList(select+" WHERE o.user_id=? AND i.id>? ORDER BY i.id LIMIT ?",a.userId(),cursor,limit+1);}else{staff(a);rows=a.realm()==Actor.Realm.MERCHANT?p.db.queryForList(select+" WHERE i.id>?"+merchantScope(a)+" ORDER BY i.id LIMIT ?",cursor,a.merchantId(),a.principalId(),limit+1):p.db.queryForList(select+" WHERE i.id>? ORDER BY i.id LIMIT ?",cursor,limit+1);}return rows.stream().map(r->view(r,a.realm()==Actor.Realm.CONSUMER)).toList();}
 private Map<String,Object> ownedStaff(Actor a,UUID application){staff(a);return a.realm()==Actor.Realm.MERCHANT?p.one(select+" WHERE i.id=?"+merchantScope(a)+" FOR UPDATE OF i",application,a.merchantId(),a.principalId()):p.one(select+" WHERE i.id=? FOR UPDATE OF i",application);}
 public Map<String,Object> detail(Actor a,UUID application,HttpServletRequest r){if(a.realm()==Actor.Realm.CONSUMER){consumer(a);return view(p.one(select+" WHERE i.id=? AND o.user_id=?",application,a.userId()),true);}staff(a);var row=a.realm()==Actor.Realm.MERCHANT?p.one(select+" WHERE i.id=?"+merchantScope(a),application,a.merchantId(),a.principalId()):p.one(select+" WHERE i.id=?",application);audit.write(a,"invoice.private.read","INVOICE",application.toString(),Map.of(),Map.of("access","PRIVATE_HEADER"),r);return view(row,true);}
 public Map<String,Object> apply(Actor a,Map<String,Object>b,String key,HttpServletRequest r){consumer(a);fields(b,"order_id","suborder_ids","title_type","title","tax_number","email");UUID order=id(b.get("order_id"));List<UUID> suborders=ids(b.get("suborder_ids"),20);if(suborders.isEmpty())throw new Failure(400,"VALIDATION_ERROR");String type=text(b.get("title_type"),16),title=text(b.get("title"),160).trim(),email=text(b.get("email"),254).trim();if(!Set.of("PERSONAL","BUSINESS").contains(type)||!email.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw new Failure(400,"VALIDATION_ERROR");String tax=b.get("tax_number")==null?null:text(b.get("tax_number"),20).trim();if(type.equals("BUSINESS")&&(tax==null||!tax.matches("[A-Z0-9]{15,20}"))||type.equals("PERSONAL")&&tax!=null)throw new Failure(400,"VALIDATION_ERROR");return commands.command(a,"invoice.apply",key,b,()->{
  p.one("SELECT o.id FROM orders o JOIN payments p ON p.order_id=o.id AND p.status='SUCCEEDED' WHERE o.id=? AND o.user_id=? FOR UPDATE OF o",order,a.userId());
  var privateData=new LinkedHashMap<String,Object>();privateData.put("title",title);privateData.put("tax_number",tax);privateData.put("email",email);String cipher=crypto.encrypt(p.json.writeValueAsString(privateData).getBytes(StandardCharsets.UTF_8));var results=new ArrayList<Map<String,Object>>();
  for(UUID sub:suborders.stream().sorted().toList()){p.one("SELECT id FROM suborders WHERE id=? AND order_id=? FOR UPDATE",sub,order);var old=p.db.queryForList("SELECT id,status,version FROM invoice_applications WHERE suborder_id=? FOR UPDATE",sub);if(!old.isEmpty()&&!old.getFirst().get("status").equals("REJECTED"))throw new Failure(409,"INVOICE_ALREADY_REQUESTED");UUID application=old.isEmpty()?UUID.randomUUID():(UUID)old.getFirst().get("id");long next=old.isEmpty()?0:number(old.getFirst().get("version"))+1;p.db.update("INSERT INTO invoice_applications(id,suborder_id,title_type,private_cipher,version) VALUES (?,?,?,?,?) ON CONFLICT(suborder_id) DO UPDATE SET title_type=excluded.title_type,private_cipher=excluded.private_cipher,status='REQUESTED',reason=NULL,version=excluded.version,updated_at=clock_timestamp()",application,sub,type,cipher,next);p.db.update("INSERT INTO invoice_application_changes(id,application_id,version,status,actor_principal_id) VALUES (?,?,?,'REQUESTED',?)",UUID.randomUUID(),application,next,a.principalId());audit.write(a,"invoice.apply","INVOICE",application.toString(),Map.of(),Map.of("suborder_id",sub),r);results.add(view(p.one(select+" WHERE i.id=?",application),false));}
  return Map.of("applications",results);
 });}
 public Map<String,Object> handle(Actor a,UUID application,Map<String,Object>b,String match,String key,String proof,HttpServletRequest r){if(a.realm()!=Actor.Realm.MERCHANT||!a.permissions().contains("invoice.handle"))throw new Failure(403,"PERMISSION_DENIED");fields(b,"status","reason");String status=text(b.get("status"),16),reason=text(b.get("reason"),500).trim();if(!Set.of("ACCEPTED","REJECTED").contains(status))throw new Failure(400,"VALIDATION_ERROR");long expected=version(match);return commands.command(a,"invoice.handle:"+application,key,Map.of("body",b,"version",expected),()->{var row=ownedStaff(a,application);sameVersion(row,expected);if(!row.get("status").equals("REQUESTED"))throw new Failure(409,"INVOICE_ALREADY_HANDLED");auth.consumeProof(a,"invoice.handle",proof);p.db.update("UPDATE invoice_applications SET status=?,reason=?,version=version+1,updated_at=clock_timestamp() WHERE id=?",status,reason,application);p.db.update("INSERT INTO invoice_application_changes(id,application_id,version,status,actor_principal_id,reason) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),application,expected+1,status,a.principalId(),reason);audit.write(a,"invoice.handle","INVOICE",application.toString(),Map.of(),Map.of("status",status,"version",expected+1),r);return view(p.one(select+" WHERE i.id=?",application),false);});}
}
